class ApiError extends Error { constructor(status, message) { super(message); this.name = "ApiError"; this.status = status; } }
class AuthError extends ApiError { constructor() { super(401, "Session expired"); this.name = "AuthError"; } }
class ForbiddenError extends ApiError { constructor() { super(403, "You do not have permission"); this.name = "ForbiddenError"; } }
class NotFoundError extends ApiError { constructor() { super(404, "Not found"); this.name = "NotFoundError"; } }
class RateLimitError extends ApiError { constructor(retryAfter) { super(429, "Too many requests"); this.name = "RateLimitError"; this.retryAfter = retryAfter; } }

function toError(res) {
  switch (res.status) {
    case 401: return new AuthError();
    case 403: return new ForbiddenError();
    case 404: return new NotFoundError();
    case 429: return new RateLimitError(Number(res.headers.get("retry-after")) || 1);
    default: return new ApiError(res.status, res.status >= 500 ? "Server problem, try again later" : "Request failed");
