async function loadWithRetry(loader, { retries = 2, delayMs = 5 } = {}) {
  for (let attempt = 0; ; attempt++) {
    try { return await loader(); }
    catch (e) {
      console.log("import attempt " + (attempt + 1) + " failed: " + e.message);
      if (attempt >= retries) throw new Error("Could not load the module. Please reload the page.", { cause: e });
      await new Promise((r) => setTimeout(r, delayMs * 2 ** attempt));
    }
  }
}
