class Widget {
  constructor(bus) {
    this.bus = bus;
    this.controller = new AbortController();
    this.count = 0;
    bus.addEventListener("tick", () => this.count++, { signal: this.controller.signal });
    this.timer = setInterval(() => {}, 1000);
  }
  destroy() {
    this.controller.abort();            // removes the listener
    clearInterval(this.timer);          // stops the interval
  }
}
